std::string decode_data(std::ifstream &infile, std::shared_ptr<Node> &root, int encoded_length) {
    std::string decoded_text;
    if (!root || encoded_length <= 0) {
        return decoded_text;
    }

    std::shared_ptr<Node> current = root;
    char byte;
    int bits_processed = 0;
    int bit_pos = 0;

    while (bits_processed < encoded_length && infile.get(byte)) {
        while (bit_pos < 8 && bits_processed < encoded_length) {
            bool bit = (byte >> (7 - bit_pos)) & 1;
            bit_pos++;
            bits_processed++;

            if (bit) {
                current = current->right;
            } else {
                current = current->left;
            }

            if (!current->left && !current->right) {
                decoded_text += current->character;
                current = root;
            }
        }
        bit_pos = 0;
    }

    return decoded_text;
}

